const assert = require('assert');
const fs = require('fs');
const path = require('path');
const { Builder, By, Key, until } = require('selenium-webdriver');
const chrome = require('selenium-webdriver/chrome');

const TIMEOUT = 10000;
const HEADLESS = (process.env.HEADLESS || 'false').toLowerCase() === 'true';

describe("Test 2", function () {
  this.timeout(180000);
  let driver;

  beforeEach(async function () {
    const options = new chrome.Options();
    if (HEADLESS) {
      options.addArguments('--headless=new', '--window-size=1920,1080', '--no-sandbox', '--disable-dev-shm-usage');
    }
    driver = await new Builder().forBrowser('chrome').setChromeOptions(options).build();
    if (!HEADLESS) {
      await driver.manage().window().maximize();
    }
  });

  afterEach(async function () {
    if (driver) {
      await driver.quit();
    }
  });

  it("Test 2", async function () {
    // No steps recorded yet
  });

  // ---------------------------------------------------------------- helpers

  async function visible(locator) {
    const element = await driver.wait(until.elementLocated(locator), TIMEOUT);
    await driver.wait(until.elementIsVisible(element), TIMEOUT);
    return element;
  }

  async function click(locator) {
    const element = await visible(locator);
    await driver.wait(until.elementIsEnabled(element), TIMEOUT);
    await element.click();
  }

  async function type(locator, text) {
    const element = await visible(locator);
    await element.clear();
    await element.sendKeys(text);
  }

  async function selectByText(locator, text) {
    const select = await visible(locator);
    for (const option of await select.findElements(By.css('option'))) {
      if ((await option.getText()).trim() === text) {
        await option.click();
        return;
      }
    }
    throw new Error('Option "' + text + '" not found');
  }

  async function settle(condition) {
    await driver.wait(async () => {
      try {
        return await condition();
      } catch (e) {
        return false;
      }
    }, TIMEOUT).catch(() => {});
  }

  async function assertText(locator, expected) {
    await settle(async () => (await driver.findElement(locator).getText()).trim() === expected);
    assert.strictEqual((await (await visible(locator)).getText()).trim(), expected);
  }

  async function assertContains(locator, expected) {
    await settle(async () => (await driver.findElement(locator).getText()).includes(expected));
    const actual = await (await visible(locator)).getText();
    assert.ok(actual.includes(expected), 'Expected "' + actual + '" to contain "' + expected + '"');
  }

  async function assertValue(locator, expected) {
    await settle(async () => (await driver.findElement(locator).getAttribute('value')) === expected);
    assert.strictEqual(await (await visible(locator)).getAttribute('value'), expected);
  }

  async function assertTitle(expected) {
    await driver.wait(until.titleIs(expected), TIMEOUT).catch(() => {});
    assert.strictEqual(await driver.getTitle(), expected);
  }

  async function assertUrlContains(expected) {
    await driver.wait(until.urlContains(expected), TIMEOUT).catch(() => {});
    const url = await driver.getCurrentUrl();
    assert.ok(url.includes(expected), 'Expected URL "' + url + '" to contain "' + expected + '"');
  }

  async function screenshot(name) {
    fs.mkdirSync('screenshots', { recursive: true });
    const safe = name.replace(/[^A-Za-z0-9._-]/g, '_');
    fs.writeFileSync(path.join('screenshots', safe + '.png'), await driver.takeScreenshot(), 'base64');
  }

  function filePath(name) {
    return path.resolve('files', name);
  }
});
